-- IELTS example fixes from the audit (see docs/ielts-review/examples-audit.md).
UPDATE ielts_examples SET sentence_en = 'Large parts of the Netherlands lie below sea level and are protected by walls.', sentence_zh = '荷兰大片地区低于海平面,靠堤坝保护。', target = 'sea level', updated_at = CURRENT_TIMESTAMP
WHERE id = 'sea-level-1' AND sentence_en = 'Much of the Netherlands lies below sea level and is protected by walls.';

UPDATE ielts_examples SET sentence_en = 'Today''s dogs are all descendants of ancient wolves.', sentence_zh = '如今的狗都是古代狼的后裔。', target = 'descendants', updated_at = CURRENT_TIMESTAMP
WHERE id = 'descendant-1' AND sentence_en = 'Today''s dogs are all descendants of the grey wolf.';

UPDATE ielts_examples SET sentence_en = 'Insects use their antennae to touch and smell things around them.', sentence_zh = '昆虫用触角触碰和嗅闻周围的东西。', target = 'antennae', updated_at = CURRENT_TIMESTAMP
WHERE id = 'antenna-1' AND sentence_en = 'Insects use each antenna to touch and smell things around them.';

UPDATE ielts_examples SET sentence_en = 'Male emperor penguins keep the eggs warm during the long Antarctic winter.', sentence_zh = '在漫长的南极冬季,雄帝企鹅负责为蛋保暖。', target = 'penguins', updated_at = CURRENT_TIMESTAMP
WHERE id = 'penguin-1' AND sentence_en = 'Male penguins keep the eggs warm during the long Antarctic winter.';

UPDATE ielts_examples SET sentence_en = 'Scientists noticed that the beak of each finch suited its particular diet.', sentence_zh = '科学家注意到,每只雀的喙都适合它特定的食物。', target = 'finch', updated_at = CURRENT_TIMESTAMP
WHERE id = 'finch-1' AND sentence_en = 'Darwin noticed that the beak of each finch suited its particular diet.';

UPDATE ielts_examples SET sentence_en = 'The wind can carry spores a long way from the parent plant.', sentence_zh = '风能把孢子带到离母株很远的地方。', target = 'spores', updated_at = CURRENT_TIMESTAMP
WHERE id = 'spore-1' AND sentence_en = 'The wind can carry each spore a long way from the parent plant.';

UPDATE ielts_examples SET sentence_en = 'Almost all animals need oxygen in order to produce energy.', sentence_zh = '几乎所有动物都需要氧气来产生能量。', target = 'oxygen', updated_at = CURRENT_TIMESTAMP
WHERE id = 'oxygen-1' AND sentence_en = 'All animals need oxygen in order to produce energy.';

UPDATE ielts_examples SET sentence_en = 'A lens bends light so that a telescope can show distant stars clearly.', sentence_zh = '透镜使光线弯曲,让望远镜能清晰地显示遥远的恒星。', target = 'lens', updated_at = CURRENT_TIMESTAMP
WHERE id = 'lens-1' AND sentence_en = 'A lens at the front of the eye focuses light onto the retina.';

UPDATE ielts_examples SET sentence_en = 'Water in the lake became more acidic after years of pollution.', sentence_zh = '多年污染后,湖水的酸性变强了。', target = 'acidic', updated_at = CURRENT_TIMESTAMP
WHERE id = 'acidic-1' AND sentence_en = 'Water in the lake became more acidic after years of pollution.';

UPDATE ielts_examples SET sentence_en = 'Smoking damages the walls of the blood vessels and raises the risk of illness.', sentence_zh = '吸烟会损害血管壁,增加患病风险。', target = 'blood vessels', updated_at = CURRENT_TIMESTAMP
WHERE id = 'blood-vessel-1' AND sentence_en = 'Smoking damages the walls of each blood vessel and raises the risk of illness.';

UPDATE ielts_examples SET sentence_en = 'Sleep affects many bodily functions, including digestion and breathing.', sentence_zh = '睡眠影响许多身体机能,包括消化和呼吸。', target = 'bodily', updated_at = CURRENT_TIMESTAMP
WHERE id = 'bodily-1' AND sentence_en = 'Sweat helps to keep bodily temperature at a safe level.';

UPDATE ielts_examples SET sentence_en = 'Oxygen passes from the blood into the tissues through tiny capillaries.', sentence_zh = '氧气通过微小的毛细血管从血液进入组织。', target = 'capillaries', updated_at = CURRENT_TIMESTAMP
WHERE id = 'capillary-1' AND sentence_en = 'Oxygen passes from the blood into the tissues through each tiny capillary.';

UPDATE ielts_examples SET sentence_en = 'My neighbour goes to the gym every day and is very muscular.', sentence_zh = '我的邻居每天去健身房,肌肉很发达。', target = 'muscular', updated_at = CURRENT_TIMESTAMP
WHERE id = 'muscular-1' AND sentence_en = 'My brother-in-law goes to the gym every day and is very muscular.';

UPDATE ielts_examples SET sentence_en = 'I think that most reality shows on television are a bit silly.', sentence_zh = '我觉得电视上的大多数真人秀都有点傻。', target = 'reality shows', updated_at = CURRENT_TIMESTAMP
WHERE id = 'reality-show-1' AND sentence_en = 'I think that every reality show on television is a bit silly.';

UPDATE ielts_examples SET sentence_en = 'The opposition party won by a narrow margin in the 2015 election.', sentence_zh = '反对党在 2015 年选举中以微弱差额获胜。', target = 'margin', updated_at = CURRENT_TIMESTAMP
WHERE id = 'margin-1' AND sentence_en = 'The Green Party won by a narrow margin in the 2015 election.';

UPDATE ielts_examples SET sentence_en = 'Children who read at home are likely to do well at school.', sentence_zh = '在家读书的孩子很可能在学校表现好。', target = 'are likely to', updated_at = CURRENT_TIMESTAMP
WHERE id = 'be-likely-to-1' AND sentence_en = 'Children from poor families are less likely to attend university.';

UPDATE ielts_examples SET sentence_en = 'Young people are often too interested in the lives of celebrities.', sentence_zh = '年轻人常常对名人的生活过于感兴趣。', target = 'celebrities', updated_at = CURRENT_TIMESTAMP
WHERE id = 'celebrity-1' AND sentence_en = 'Young people are often too interested in the lives of each celebrity.';

UPDATE ielts_examples SET sentence_en = 'Some pesticides do more harm than good in the long term.', sentence_zh = '从长远来看,有些农药弊大于利。', target = 'harm', updated_at = CURRENT_TIMESTAMP
WHERE id = 'harm-1' AND sentence_en = 'Most pesticides do more harm than good in the long term.';
